// The app around the grid: stateless per session, no server calls, no
// persistence. The sample workbook is inlined at build time; people may open
// their own .xlsx and download the Forge-generated bytes at the end.
//
// The normal view always runs `not-execute` (Forge calculates, Univer is only
// the view). `?dev=1`, or any other `?mode=`, shows the Developer strip with
// the mode selector, the raw revision and the source state.
import { startForgeWorker } from '@workbook-forge/engine';
import catalog from 'virtual:forge-catalog';
import fixtureDataUrl from '../../../fixtures/univer-spike-chain.xlsx?inline';
import { toA1 } from './a1';
import { ForgeUniverAdapter, type NoticeKind } from './adapter';
import { CATEGORY_LABELS, FUNCTION_NOTES, arityText, parseArguments } from './function-notes';
import { MODES, createUniverHost, type Mode } from './univer-host';
import './shell.css';

const DEFAULT_MODE: Mode = 'not-execute';
const params = new URLSearchParams(location.search);
const requested = params.get('mode') ?? '';
const mode = (MODES as readonly string[]).includes(requested) ? (requested as Mode) : DEFAULT_MODE;
const devMode = params.get('dev') === '1' || mode !== DEFAULT_MODE;

const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
const el = <K extends keyof HTMLElementTagNameMap>(tag: K, props: Partial<HTMLElementTagNameMap[K]> = {}, children: (Node | string)[] = []) => {
  const node = Object.assign(document.createElement(tag), props);
  node.append(...children);
  return node;
};

const select = $<HTMLSelectElement>('mode');
for (const m of MODES) select.add(new Option(m, m, m === mode, m === mode));
select.onchange = () => {
  params.set('mode', select.value);
  location.search = params.toString();
};
$('developer').hidden = !devMode;

// Theme: follows the device setting on load. The toggle lasts for this visit
// only; nothing is stored.
let dark = matchMedia('(prefers-color-scheme: dark)').matches;
const themeToggle = $<HTMLButtonElement>('theme-toggle');
function paintTheme() {
  document.documentElement.dataset.theme = dark ? 'dark' : 'light';
  themeToggle.setAttribute('aria-label', dark ? 'Switch to light theme' : 'Switch to dark theme');
}
paintTheme();

type Diagnostic = { code?: string; message?: string; sheet?: string; address?: string };
type Range = { startRow: number; endRow: number; startColumn: number; endColumn: number };
type PanelView = 'functions' | 'issues' | 'array';

function decodeDataUrl(url: string): Uint8Array {
  const base64 = url.slice(url.indexOf(',') + 1);
  return Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
}

/** A total as a status bar shows it: grouped, without binary-float noise. */
function formatNumber(value: number): string {
  return value.toLocaleString('en-US', { maximumSignificantDigits: 12 });
}

// ---------- Messages ----------

const notice = $('notice');
const notices = $('notices');
let noticeTimer: number | undefined;
/** Show one message. Information fades after a while; errors stay until dismissed. */
function showNotice(text: string, kind: NoticeKind = 'error') {
  clearTimeout(noticeTimer);
  notices.textContent = text;
  notice.dataset.kind = kind;
  notice.hidden = text === '';
  if (text !== '' && kind === 'info') noticeTimer = window.setTimeout(() => showNotice(''), 9000);
}
$('notice-close').onclick = () => showNotice('');

// ---------- Function reference ----------

const functionSearch = $<HTMLInputElement>('function-search');
const functionCount = $('function-count');
const functionEntries: { item: HTMLElement; group: HTMLElement; text: string }[] = [];

function buildFunctionReference() {
  const total = catalog.functions.length;
  $('function-coverage').textContent =
    `Workbook Forge calculates ${total} of the ${catalog.inventoried} functions in Microsoft's Excel function list. ` +
    'A formula that uses any other function stays blank and is listed under Formula issues.';
  const known = new Map(CATEGORY_LABELS);
  const categories = [...CATEGORY_LABELS.map(([id]) => id), ...new Set(catalog.functions.map((f) => f.category).filter((c) => !known.has(c)))];
  const list = $('function-list');
  for (const category of categories) {
    const functions = catalog.functions.filter((f) => f.category === category).sort((a, b) => a.name.localeCompare(b.name));
    if (functions.length === 0) continue;
    const label = known.get(category) ?? category;
    const items = el('ul');
    const group = el('section', { className: 'fn-group' }, [el('h3', {}, [label, el('span', { textContent: String(functions.length) })]), items]);
    for (const fn of functions) {
      const note = FUNCTION_NOTES[fn.name];
      const signature = el('code', {}, [el('b', { textContent: fn.name }), `(${note?.args ?? ''})`]);
      const item = el('li', { className: 'fn' }, [signature, el('p', { textContent: note?.summary ?? arityText(fn.min, fn.max) })]);
      if (note?.limit) item.append(el('p', { className: 'limit', textContent: note.limit }));
      items.append(item);
      functionEntries.push({ item, group, text: `${fn.name} ${note?.summary ?? ''}`.toLowerCase() });
    }
    list.append(group);
  }
  list.append(el('p', { id: 'function-empty', className: 'empty', hidden: true }));
  filterFunctions();
}

function filterFunctions() {
  const words = functionSearch.value.toLowerCase().split(/\s+/).filter(Boolean);
  const groups = new Map<HTMLElement, number>();
  let shown = 0;
  for (const entry of functionEntries) {
    const match = words.every((word) => entry.text.includes(word));
    entry.item.hidden = !match;
    groups.set(entry.group, (groups.get(entry.group) ?? 0) + (match ? 1 : 0));
    if (match) shown += 1;
  }
  for (const [group, count] of groups) group.hidden = count === 0;
  const total = functionEntries.length;
  functionCount.textContent = words.length === 0 ? `${total} functions` : `${shown} of ${total} functions`;
  const empty = $('function-empty');
  empty.hidden = shown > 0;
  empty.textContent = `No function Workbook Forge calculates matches "${functionSearch.value.trim()}".`;
}
functionSearch.oninput = filterFunctions;

async function boot() {
  const { client } = startForgeWorker();
  const host = await createUniverHost($('app'), mode, { darkMode: dark });
  const adapter = new ForgeUniverAdapter(host, client);
  adapter.setNoticeSink(showNotice);
  buildFunctionReference();

  themeToggle.onclick = () => {
    dark = !dark;
    paintTheme();
    host.univerAPI.toggleDarkMode(dark);
  };

  // ---------- Side panel ----------

  const panel = $('panel');
  const panelTitle = $('panel-title');
  const views: Record<PanelView, { section: HTMLElement; title: string; toggle?: HTMLElement }> = {
    functions: { section: $('functions'), title: 'Functions', toggle: $('functions-toggle') },
    issues: { section: $('formula-issues'), title: 'Formula issues', toggle: $('issues-toggle') },
    array: { section: $('array-result'), title: 'Array result' },
  };
  let panelView: PanelView | null = null;
  const showPanel = (view: PanelView | null) => {
    panelView = view;
    panel.hidden = view === null;
    for (const [name, { section, toggle }] of Object.entries(views)) {
      section.hidden = name !== view;
      toggle?.setAttribute('aria-expanded', String(name === view));
    }
    if (view) panelTitle.textContent = views[view].title;
  };
  const togglePanel = (view: PanelView) => showPanel(panelView === view ? null : view);
  $('functions-toggle').onclick = () => {
    togglePanel('functions');
    if (panelView === 'functions' && matchMedia('(min-width: 721px)').matches) functionSearch.focus();
  };
  $('issues-toggle').onclick = () => togglePanel('issues');
  $('panel-close').onclick = () => showPanel(null);

  const fixture = decodeDataUrl(fixtureDataUrl);
  // What the status line names, and the Developer strip's source state.
  let source = { name: 'univer-spike-chain.xlsx', kind: 'built-in sample (.xlsx)' };
  await adapter.open(fixture, 'univer-spike-chain');
  // Where Forge is the calculator, the in-cell suggestions and argument help
  // list what Forge calculates, in the same words as the Functions panel. The
  // control mode keeps Univer's own list: there Univer calculates too.
  if (mode !== 'univer-default') {
    host.setFunctionHelp(
      catalog.functions.map((fn) => {
        const note = FUNCTION_NOTES[fn.name];
        const summary = note?.summary ?? arityText(fn.min, fn.max);
        return { name: fn.name, summary, detail: note?.limit ? `${summary} ${note.limit}` : summary, args: parseArguments(note?.args ?? '') };
      }),
    );
  }

  /** Put the selection on one cell, switching sheets when needed. */
  const goTo = (sheet: string | undefined, address: string | undefined) => {
    if (!address) return;
    const workbook = host.univerAPI.getActiveWorkbook();
    const target = sheet ? workbook?.getSheetByName(sheet) : workbook?.getActiveSheet();
    if (!workbook || !target) return;
    if (target.getSheetId() !== workbook.getActiveSheet().getSheetId()) workbook.setActiveSheet(target);
    target.getRange(address).activate();
  };

  // ---------- Formula issues ----------
  // Forge's calculation diagnostics (formulas it refuses, such as an XLOOKUP
  // match mode outside the supported subset). Read once per revision, when no
  // edit is in flight; the toolbar button shows only while there are some.
  const issuesToggle = $('issues-toggle');
  const issueCount = $('formula-issue-count');
  const issueList = $('formula-issue-list');
  let issuesFor: string | null = null;
  let issuesBusy = false;
  const refreshIssues = async () => {
    const key = `${source.name}#${adapter.revision}`;
    if (issuesBusy || adapter.pending > 0 || key === issuesFor) return;
    issuesBusy = true;
    try {
      const calc = await client.calculate();
      if (!calc.ok || calc.value.revision !== adapter.revision) return;
      const found = calc.value.diagnostics as Diagnostic[];
      issuesFor = key;
      issueCount.textContent = String(found.length);
      issueList.replaceChildren(
        ...found.map((d) => {
          const where = d.address ? `${d.sheet ? `${d.sheet}!` : ''}${d.address}` : (d.sheet ?? '');
          const what = d.message || d.code || 'formula could not be calculated';
          const button = el('button', { type: 'button', className: 'issue' }, [...(where ? [el('b', { textContent: where })] : []), what]);
          button.onclick = () => goTo(d.sheet, d.address);
          return el('li', {}, [button]);
        }),
      );
      issuesToggle.hidden = found.length === 0;
      issuesToggle.title = found.length === 1 ? '1 formula could not be calculated' : `${found.length} formulas could not be calculated`;
      if (found.length === 0 && panelView === 'issues') showPanel(null);
    } finally {
      issuesBusy = false;
    }
  };

  // ---------- Selection: totals and array preview ----------

  const stats = $('selection-stats');
  const arrayChip = $('array-chip');
  const arrayNote = $('array-note');
  const arrayTable = $<HTMLTableElement>('array-table');
  const MAX_PREVIEW = { rows: 200, columns: 50 };
  let selections: Range[] = [];
  let selectionFor = '';
  const paintSelection = () => {
    const sheet = adapter.activeSheetName();
    const key = `${source.name}#${adapter.revision}#${sheet}#${JSON.stringify(selections)}`;
    if (key === selectionFor) return;
    selectionFor = key;
    const parts: [string, string][] = [];
    if (sheet && selections.length > 0) {
      const summary = adapter.summarize(sheet, selections);
      if (summary.count > 1) {
        if (summary.numbers > 0) parts.push(['Average', formatNumber(summary.sum / summary.numbers)]);
        parts.push(['Count', formatNumber(summary.count)]);
        if (summary.numbers > 0) parts.push(['Sum', formatNumber(summary.sum)]);
      }
    }
    stats.replaceChildren(...parts.map(([label, value]) => el('span', {}, [`${label} `, el('b', { textContent: value })])));

    const only = selections.length === 1 && selections[0].startRow === selections[0].endRow && selections[0].startColumn === selections[0].endColumn ? selections[0] : null;
    const address = only ? toA1(only.startRow, only.startColumn) : null;
    const rows = sheet && address ? adapter.arrayResult(sheet, address) : null;
    if (!rows) {
      arrayChip.hidden = true;
      if (panelView === 'array') showPanel(null);
      return;
    }
    const columns = Math.max(0, ...rows.map((row) => row.length));
    arrayChip.hidden = false;
    arrayChip.textContent = `Array result: ${rows.length} by ${columns}`;
    const clipped = rows.length > MAX_PREVIEW.rows || columns > MAX_PREVIEW.columns;
    arrayNote.textContent =
      `The formula in ${address} returns ${rows.length} ${rows.length === 1 ? 'row' : 'rows'} by ${columns} ${columns === 1 ? 'column' : 'columns'}. ` +
      'Workbook Forge does not place array results into neighboring cells yet, so the cell stays blank and the values are shown here.' +
      (clipped ? ` Showing the first ${Math.min(rows.length, MAX_PREVIEW.rows)} rows and ${Math.min(columns, MAX_PREVIEW.columns)} columns.` : '');
    arrayTable.replaceChildren(
      ...rows.slice(0, MAX_PREVIEW.rows).map((row) =>
        el(
          'tr',
          {},
          Array.from({ length: Math.min(columns, MAX_PREVIEW.columns) }, (_, c) => {
            const value = row[c] ?? null;
            if (value === null) return el('td', { className: 'blank' });
            if (typeof value === 'number') return el('td', { className: 'num', textContent: String(value) });
            if (typeof value === 'boolean') return el('td', { textContent: value ? 'TRUE' : 'FALSE' });
            return el('td', { textContent: typeof value === 'string' ? value : value.error });
          }),
        ),
      ),
    );
    if (panelView === null) showPanel('array');
  };
  arrayChip.onclick = () => showPanel('array');
  // Read from the active sheet each time rather than from Univer's selection
  // events: those stay bound to the first workbook, and every New or Open
  // makes a fresh one.
  const readSelection = () => {
    // A whole row or column arrives without the other axis; treat it as open-ended.
    const bound = (value: number, fallback: number) => (Number.isFinite(value) ? value : fallback);
    const ranges = host.univerAPI.getActiveWorkbook()?.getActiveSheet().getSelection()?.getActiveRangeList() ?? [];
    selections = ranges.map((range) => {
      const r = range.getRange();
      return {
        startRow: bound(r.startRow, 0),
        endRow: bound(r.endRow, Number.MAX_SAFE_INTEGER),
        startColumn: bound(r.startColumn, 0),
        endColumn: bound(r.endColumn, Number.MAX_SAFE_INTEGER),
      };
    });
    paintSelection();
  };
  host.univerAPI.addEvent(host.univerAPI.Event.CommandExecuted, (event) => {
    if (event.id === 'sheet.operation.set-selections') readSelection();
  });

  // ---------- Status ----------

  const docName = $('doc-name');
  const calcState = $('calc-state');
  const version = $('version');
  const devRevision = $('dev-revision');
  const devSource = $('dev-source');
  const devBlocked = $('dev-blocked');
  const showStatus = () => {
    // A failed or closed engine is terminal: say so rather than "Calculating…"
    // or a calculated state that no longer holds.
    const engine = client.state;
    const stopped = engine.kind === 'failed' || engine.kind === 'closed';
    const state =
      engine.kind === 'failed' ? `Engine stopped: ${engine.error.message}` : engine.kind === 'closed' ? 'Engine closed' : adapter.pending > 0 ? 'Calculating…' : 'All changes calculated';
    docName.textContent = source.name;
    calcState.textContent = state;
    calcState.dataset.state = stopped ? 'stopped' : adapter.pending > 0 ? 'busy' : 'ready';
    version.textContent = `Version ${adapter.revision}`;
    document.title = `${source.name} · Workbook Forge`;
    if (devMode) {
      devRevision.textContent = `Forge r${adapter.revision} · mode ${mode}`;
      devSource.textContent = `${source.kind}: ${source.name}`;
      devBlocked.textContent = adapter.audit.blocked.at(-1) ?? 'none';
    }
    readSelection();
    // Lifecycle failures already show in the status line.
    refreshIssues().catch(() => {});
  };
  showStatus();
  setInterval(showStatus, 250);

  $('undo').onclick = () => adapter.undo();
  $('redo').onclick = () => adapter.redo();
  /** Replace the workbook, keeping the current one on screen when that fails. */
  const replace = async (next: { name: string; kind: string }, load: () => Promise<void>, failure: string) => {
    try {
      // Clear first. Loading paints notices while it projects, and a clear
      // after success would erase them.
      showNotice('');
      await load();
      source = next;
      issuesFor = null;
      if (panelView !== 'functions') showPanel(null);
      showStatus();
    } catch (error) {
      showNotice(`${failure}: ${String(error)}`);
    }
  };
  $('new').onclick = () => replace({ name: 'New workbook', kind: 'new blank workbook' }, () => adapter.newWorkbook('Sheet1'), 'Could not create workbook');
  $('file').onchange = async (event) => {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) return;
    const bytes = new Uint8Array(await file.arrayBuffer());
    await replace({ name: file.name, kind: 'opened from this device (.xlsx)' }, () => adapter.open(bytes, file.name), `Could not open ${file.name}`);
    input.value = '';
  };
  $('export').onclick = async () => {
    try {
      const bytes = await adapter.exportXlsx();
      const link = document.createElement('a');
      link.href = URL.createObjectURL(new Blob([bytes as BlobPart], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }));
      link.download = /\.xlsx$/i.test(source.name) ? source.name : 'workbook.xlsx';
      link.click();
      URL.revokeObjectURL(link.href);
    } catch (error) {
      showNotice(`Could not download: ${String(error)}`);
    }
  };
  return { adapter, host, client, fixture, mode, startForgeWorker };
}

declare global {
  interface Window {
    __spike: Promise<Awaited<ReturnType<typeof boot>>>;
  }
}
window.__spike = boot();
